def number(x):
    try:
        v = float(x)
        return v if math.isfinite(v) else None
    except (TypeError, ValueError):
        return None


def avg(xs):
    values = [v for x in xs if (v := number(x)) is not None]
    return statistics.mean(values) if values else None


def sd(xs):
    values = [v for x in xs if (v := number(x)) is not None]
    return statistics.stdev(values) if len(values) > 1 else None


def digest(value):
    if isinstance(value, bytes):
        return hashlib.sha256(value).hexdigest()
    h = hashlib.sha256()
    with Path(value).open("rb") as f:
        for chunk in iter(lambda: f.read(1048576), b""):
            h.update(chunk)
    return h.hexdigest()


def clean(x):
    if isinstance(x, float) and not math.isfinite(x):
        return None
    if isinstance(x, dict):
        return {str(k): clean(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [clean(v) for v in x]
    return x


def save_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(json.dumps(clean(obj), ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")
    os.replace(tmp, path)


def read_json(path):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8-sig"))
    except (ValueError, OSError):
        return {}


def save_csv(path, rows):
    fields = list(dict.fromkeys(k for row in rows for k in row)) or ["status"]
    with Path(path).open("w", encoding="utf-8-sig", newline="") as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for row in rows:
            w.writerow({k: json.dumps(clean(v), ensure_ascii=False) if isinstance(v, (dict, list, tuple)) else v for k, v in row.items()})


def inside(path, parent):
    return Path(path).resolve().is_relative_to(Path(parent).resolve())


def actual_control(task):
    # E0的J3名称不等于飞机有学习控制权。
    return "J3" if task.get("environment") == "E1" and (
        task.get("control") == "J3" or str(task.get("method", "")).startswith("J3")) else "LQ"


def locate(name):
    parts = PurePosixPath(name.replace("\\", "/")).parts
    for i, part in enumerate(parts):
        if part in SUITES:
            return part, "/".join(parts[i + 1:])
    return None, None


def cell_name(rel):
    parts = rel.split("/")
    if "cells" in parts:
        i = parts.index("cells")
        return parts[i + 1] if i + 1 < len(parts) else ""
    if "calibration" in parts:
        i = parts.index("calibration")
        return parts[i + 1] if i + 1 < len(parts) else ""
    if "rules" in parts:
        return "RULES__" + "__".join(parts[1:-1])
    if "cases" in parts:
        return parts[parts.index("cases") + 1]
    return ""


def infer_task(suite, cell, rel=""):
    task = {"id": cell, "environment": "E0" if "source_K234" in suite else None}
    for key, pattern in (("k", r"(?:^|__)K([234])(?:__|$)"), ("seed", r"__s(\d+)$"), ("fleet", r"__N(\d+)(?:__|$)")):
        m = re.search(pattern, cell)
        if m:
            task[key] = int(m[1])
    m = re.search(r"(?:^|__)(E[01])(?:__|$)", cell)
    if m:
        task["environment"] = m[1]
    if "k" not in task:
        m = re.search(r"(?:^|/)K([234])(?:/|$)", rel)
        if m:
            task["k"] = int(m[1])
    if "strictE1" in suite and not task.get("environment"):
        task["environment"] = "E1"
    task["method"] = re.sub(r"__s\d+$", "", cell)
    return task


def timeline_audit(ep, capacity=4):
    """只按真实记录的采样点描述，不把五分钟快照当精确逐分钟等待。"""
    rows = ep.get("resource_timeline") or []
    categories = Counter()
    mismatches = 0
    gaps = []
    for i, row in enumerate(rows):
        if i:
            a, b = number(rows[i - 1].get("time")), number(row.get("time"))
            if a is not None and b is not None:
                gaps.append(b - a)
        stations = [k[1:-6] for k in row if k.startswith("V") and k.endswith("_queue") and k != "V2_queue"]
        queues = {v: number(row.get("V" + v + "_queue")) for v in stations}
        ready = {v: number(row.get("V" + v + "_ready")) for v in stations}
        if any(v is None for v in list(queues.values()) + list(ready.values())):
            continue
        for v in stations:
            q, a = queues[v], ready[v]
            cat = "both_ready" if q >= capacity and a > 0 else "batch_ready_aircraft_missing" if q >= capacity else "batch_missing_aircraft_ready" if a > 0 else "both_missing"
            categories[cat] += 1
        mismatches += int(any(queues[v] >= capacity and ready[v] == 0 for v in stations) and any(ready[v] > 0 for v in stations))
    return dict(timeline_samples=len(rows), snapshot_station_categories=dict(categories),
                spatial_mismatch_samples=mismatches, snapshot_max_interval=max(gaps) if gaps else None,
                timeline_scope="采样点描述；不是精确等待时间分解")


def temporal_audit(ep):
    """检验原始输入与物理摘要的可观测差异；不声称已证明STIN隐藏层丢信息。"""
    trace = ep.get("decision_trace") or []
    channels, opportunities, missing = [], 0, 0
    for row in trace:
        frame = row.get("source_current_frame") or []
        stations = row.get("pre_committed_station_summary") or []
        for i, station in enumerate(stations):
            indexes = [4 + 8 * i + j for j in (5, 6, 7)]
            if max(indexes, default=0) >= len(frame):
                continue
            values = [number(frame[j]) for j in indexes]
            channels.extend(v for v in values if v is not None)
            ready = number(station.get("next_committed_ready"))
            if ready is not None and ready > 0:
                opportunities += 1
                missing += int(all(v == 0 for v in values))
    return dict(decision_samples=len(trace), source_time_values=len(channels),
                source_time_zero_fraction=sum(v == 0 for v in channels) / len(channels) if channels else None,
                positive_ready_samples=opportunities, zero_time_with_positive_ready=missing,
                temporal_claim="仅输入通道描述，不能据此宣布编码压缩、动作反转或ATT因果损失")


def terminal_label(ep):
    n, f = number(ep.get("generated")), number(ep.get("finished"))
    if n is not None and f is not None and n == f:
        return "COMPLETE"
    queues = ep.get("final_station_queues")
    if not isinstance(queues, dict):
        return "UNKNOWN_NO_FINAL_QUEUES"
    q = [number(v) for v in queues.values()]
    if n is None or f is None or not q or any(v is None for v in q) or sum(q) != n - f:
        return "UNKNOWN_NONQUEUE_OR_BOUNDARY"
    if all(v < 4 for v in q):
        return "TAIL_BATCH_COMPATIBLE_NOT_PROVEN"
    # 没有请求穷尽、全机状态与执行器证明，就不宣称永远卡死。
    return "FULL_BATCH_BACKLOG_NEEDS_REPLAY"


class Audit:
    def __init__(self, args, out):
        self.args, self.out = args, out
        self.meta, self.plans, self.episodes, self.inputs = {}, {}, {}, []
        self.issues, self.probes, self.replay_diagnostics = [], [], []
        self.seen_files, self.bytes, self.files = {}, 0, 0
        self.trace_hashes = defaultdict(set)

    def issue(self, source, reason):
        self.issues.append(dict(source=source, reason=reason))

    def accept(self, name, data, source):
        suite, rel = locate(name)
        if suite is None:
            return
        sha = digest(data)
        key = (suite, rel)
        if key in self.seen_files:
            if self.seen_files[key] != sha:
                self.issue(source, "同实验同路径出现异构快照，保留首先读入版本；不能合并成同一记录：" + rel)
            return
        self.seen_files[key] = sha
        self.files += 1
        self.bytes += len(data)
        if self.files > self.args.max_files or self.bytes > self.args.max_read_gib * 1024**3:
            raise RuntimeError("达到读取预算；本次标为未完成，不把截断当完整分析")
        if rel.endswith("passengers_300.csv") and "/train_data/" in rel:
            self.trace_hashes[suite].add(sha)
            return
        if not rel.endswith(".json"):
            return
        try:
            obj = json.loads(data.decode("utf-8-sig"))
        except (UnicodeError, ValueError) as e:
            self.issue(source + "!" + rel, type(e).__name__)
            return
        if not isinstance(obj, dict):
            return
        if rel.endswith("AUTHOR_SOURCE_MANIFEST.json"):
            source_files = obj.get("files", obj)
            trace_hash = source_files.get("train_data/passengers_300.csv") if isinstance(source_files, dict) else None
            if isinstance(trace_hash, str) and re.fullmatch("[0-9a-f]{64}", trace_hash):
                self.trace_hashes[suite].add(trace_hash)
        cell = cell_name(rel)
        if rel == "SUITE_PLAN.json":
            self.plans[suite] = obj
        if isinstance(obj.get("task"), dict) and cell:
            self.meta[(suite, cell)] = obj["task"]
        if rel.endswith("PROBE.json"):
            task = obj.get("task", {})
            for i, probe in enumerate(obj.get("probes") or []):
                costs = [number(v) for v in probe.get("branch_costs", [])]
                self.probes.append(dict(suite=suite, cell=task.get("id", cell), index=i,
                    environment=task.get("environment"), k=task.get("k"), seed=task.get("seed"),
                    recorded_excess=probe.get("chosen_cost_excess"), branch_costs=costs,
                    legacy_label_validated=False, scope="旧有限分支仅作线索；首步计账、RNG和窗口边界尚未由本脚本验证"))
            return
        if "original_episode_metrics" in obj and "job" in obj:
            self.replay_diagnostics.append(dict(suite=suite, source=source + "!" + rel,
                job=obj.get("job"), completion=obj.get("completion"),
                first_structural_stall=obj.get("first_structural_stall"),
                replay_seconds=obj.get("replay_seconds"), comparable=obj.get("comparable_to_formal")))
        eps = obj.get("episodes")
        if not isinstance(eps, list):
            eps = [obj] if "generated" in obj and "finished" in obj else []
        # 派生索引、计时摘要和重复的汇总文件不额外制造回放样本。
        step_match = re.search(r"step_(\d+)", rel)
        step = int(step_match[1]) if step_match else None
        rule_context = "/rules/" in "/" + rel or "/calibration/" in "/" + rel or cell.startswith("RULES") or "SPF_STTF_QTTI" in suite
        if not eps or not cell or (not step and not rule_context and "/cases/" not in "/" + rel):
            return
        for i, ep in enumerate(eps):
            if not isinstance(ep, dict) or "generated" not in ep:
                continue
            task = dict(obj.get("task") or self.meta.get((suite, cell)) or infer_task(suite, cell, rel))
            for key in ("environment", "k", "fleet"):
                if key in ep:
                    task[key] = ep[key]
            mode = str(ep.get("mode") or ("RULE" if rule_context else "DET"))
            rule = ep.get("rule") or (mode if rule_context else None)
            if rule_context and (not rule or rule in ("DET", "RULE")):
                rule = ep.get("policy") or task.get("method") if "SPF_STTF_QTTI" in suite else ep.get("policy") or re.sub(r"__s\d+$", "", Path(rel).stem)
            if rule_context:
                mode = str(rule)
            bank = ep.get("trace_sha256") or "trace_index:" + str(ep.get("trace_index", 0))
            rowkey = (suite, cell, step, str(ep.get("eval_seed", i)), mode, bank, str(rule))
            n, f = number(ep.get("generated")), number(ep.get("finished"))
            co, all_att = number(ep.get("ATT_completed_only")), number(ep.get("ATT"))
            flags = []
            if n is None or n <= 0 or f is None or not 0 <= f <= n:
                flags.append("人数缺失或越界")
            completion = f / n if n and f is not None else None
            c = number(ep.get("completion"))
            if c is not None and completion is not None and abs(c - completion) > 1e-8:
                flags.append("完成率与人数不符")
            if completion is not None and completion < 1 and all_att is not None:
                flags.append("未全完成却填写全体ATT，禁止混排")
            passengers = ep.get("passengers") or []
            pmean = avg(p.get("travel") for p in passengers if isinstance(p, dict))
            component = avg(number(p.get("travel")) - sum(number(p.get(k)) or 0 for k in ("ground", "wait", "flight"))
                            for p in passengers if isinstance(p, dict) and number(p.get("travel")) is not None)
            row = dict(suite=suite, cell=cell, step=step, eval_seed=ep.get("eval_seed", i), mode=mode,
                bank=bank, rule=rule, task=task, source=source + "!" + rel,
                generated=n, finished=f, completion=completion, co=co, all_att=all_att,
                rpt=number(ep.get("restricted_person_time_per_generated")),
                ground=number(ep.get("AGT_completed_only")), wait=number(ep.get("AWT_completed_only")),
                flight=number(ep.get("AFT_completed_only")), sim_minutes=number(ep.get("simulation_minutes")),
                wall_seconds=number(ep.get("wall_seconds")), terminal_class=terminal_label(ep),
                passenger_rows=len(passengers), passenger_mean_check=pmean,
                co_recompute_error=pmean - co if pmean is not None and co is not None else None,
                component_residual=component, final_queues=ep.get("final_station_queues"),
                lifecycle=ep.get("lifecycle") or {}, control_diagnostics=ep.get("control_diagnostics") or {},
                flags=flags, privileged="oracle" in suite, **timeline_audit(ep), **temporal_audit(ep))
            old = self.episodes.get(rowkey)
            if old is None or row["decision_samples"] + row["timeline_samples"] > old["decision_samples"] + old["timeline_samples"]:
                self.episodes[rowkey] = row

    def scan(self, sources):
        for source in sources:
            source = Path(source).resolve()
            print("[读取]", source, flush=True)
            if source.is_symlink():
                self.issue(str(source), "拒绝符号链接输入")
                continue
            signature = dict(path=str(source), size=source.stat().st_size if source.is_file() else None)
            if source.is_file():
                signature["sha256"] = digest(source)
                with tarfile.open(source, "r|gz") as arc:
                    for member in arc:
                        parts = PurePosixPath(member.name).parts
                        if member.issym() or member.islnk() or ".." in parts or member.name.startswith("/"):
                            self.issue(str(source) + "!" + member.name, "拒绝链接或不安全成员；从不解压")
                            continue
                        if member.isfile() and member.name.endswith((".json", ".csv")) and member.size <= self.args.max_member_mib * 1024**2:
                            with arc.extractfile(member) as f:
                                self.accept(member.name, f.read(), str(source))
                        elif member.isfile() and member.name.endswith((".json", ".csv")):
                            self.issue(str(source) + "!" + member.name, "超过单文件预算，明确保留缺失")
            elif source.is_dir():
                if source.name not in SUITES:
                    raise RuntimeError("目录输入必须是明确支持的实验根目录")
                for folder, dirs, files in os.walk(source, followlinks=False):
                    dirs[:] = sorted(d for d in dirs if d not in ("checkpoints", "training", "test", "banks", "__pycache__") and not (Path(folder) / d).is_symlink())
                    for filename in sorted(files):
                        path = Path(folder) / filename
                        if path.suffix not in (".json", ".csv") or path.is_symlink():
                            continue
                        if path.stat().st_size > self.args.max_member_mib * 1024**2:
                            self.issue(str(path), "超过单文件预算")
                            continue
                        try:
                            before = path.stat()
                            data = path.read_bytes()
                            after = path.stat()
                            if before.st_mtime_ns != after.st_mtime_ns or before.st_size != after.st_size:
                                self.issue(str(path), "正在写入，跳过本次不一致快照")
                                continue
                            self.accept(source.name + "/" + path.relative_to(source).as_posix(), data, str(source))
                        except OSError as e:
                            self.issue(str(path), type(e).__name__)
            self.inputs.append(signature)

    def finish(self):
        episodes = list(self.episodes.values())
        for row in episodes:
            task = dict(self.meta.get((row["suite"], row["cell"])) or {}) | row.pop("task")
            row.pop("task", None)
            row.update(environment=task.get("environment") or ("E0" if "source_K234" in row["suite"] else None),
                k=task.get("k"), fleet=task.get("fleet"), seed=task.get("seed"), stage=task.get("stage", task.get("phase", "")),
                method=task.get("method", task.get("variant", row["cell"])), control=actual_control(task),
                arm=task.get("variant") or task.get("arm") or task.get("method", row["cell"]))
            if row["rule"] == "READY_QUEUE_JOINT" and row["environment"] == "E1":
                row["control"] = "J3"
            if row["environment"] == "E1" and row["fleet"] is None and row["suite"] in SUITES[3:7]:
                row["fleet"] = 12
            hashes = self.trace_hashes[row["suite"]]
            row["trace_key"] = row["bank"] if not row["bank"].startswith("trace_index:") else next(iter(hashes)) if len(hashes) == 1 else "UNKNOWN:" + row["bank"]
            row["baseline_scope"] = "同suite、环境、K、机队、实际控制、trace、eval_seed、实际时域；未证明跨suite训练合同相同"
        # 只汇总DET；STO保留在原始表，不与确定性回放混排。
        groups = defaultdict(list)
        for row in episodes:
            if row["step"] is not None and row["mode"] == "DET" and not row["rule"] and not row["privileged"]:
                groups[(row["suite"], row["cell"], row["step"])].append(row)
        curves = []
        for (suite, cell, step), rows in sorted(groups.items()):
            head = rows[0]
            curves.append({k: head[k] for k in ("suite", "cell", "environment", "k", "fleet", "seed", "stage", "method", "control", "arm")} |
                dict(step=step, co=avg(r["co"] for r in rows), rpt=avg(r["rpt"] for r in rows),
                     completion=avg(r["completion"] for r in rows), episodes=len(rows),
                     bank_signature=sorted((r["trace_key"], str(r["eval_seed"])) for r in rows),
                     full_att=avg(r["all_att"] for r in rows) if all(r["completion"] == 1 for r in rows) else None))
        byrun = defaultdict(list)
        for row in curves:
            byrun[(row["suite"], row["cell"])].append(row)
        runs = []
        selected = set()
        for key, rows in sorted(byrun.items()):
            rows.sort(key=lambda r: r["step"])
            valid = [r for r in rows if r["co"] is not None]
            if not valid:
                continue
            best = min(valid, key=lambda r: (r["co"], r["step"]))
            late = [r for r in rows if r["step"] >= .8 * rows[-1]["step"]]
            head = {k: best[k] for k in ("suite", "cell", "environment", "k", "fleet", "seed", "stage", "method", "control", "arm")}
            runs.append(head | dict(best_co=best["co"], best_step=best["step"], best_completion=best["completion"],
                best_rpt=best["rpt"], late_co=avg(r["co"] for r in late), late_sd=sd(r["co"] for r in late),
                final_co=rows[-1]["co"], final_completion=rows[-1]["completion"],
                rollback=avg(r["co"] for r in late) - best["co"], checkpoint_count=len(rows),
                evaluation_scope="归档内Best选择，非独立测试；末20%按现有末点描述，未满训须看任务状态",
                warm_start="48m" in key[0], bank_signature=best["bank_signature"]))
            selected.add((key[0], key[1], best["step"]))
        # 规则逐条列出，不按测试回放的最小值悄悄挑出一个冠军。
        rules_index = defaultdict(lambda: defaultdict(list))
        for r in episodes:
            if r["rule"] and not r["privileged"]:
                rules_index[self.match_key(r)][str(r["rule"])].append(r)
        comparisons = []
        for row in episodes:
            if (row["suite"], row["cell"], row["step"]) not in selected or row["mode"] != "DET" or row["rule"]:
                continue
            for rule, values in rules_index.get(self.match_key(row), {}).items():
                if row["trace_key"].startswith("UNKNOWN:"):
                    continue
                co, comp = avg(v["co"] for v in values), avg(v["completion"] for v in values)
                comparisons.append(dict(suite=row["suite"], cell=row["cell"], method=row["method"], seed=row["seed"],
                    environment=row["environment"], k=row["k"], control=row["control"], rule=rule,
                    eval_seed=row["eval_seed"], trace_key=row["trace_key"], step=row["step"],
                    delta_co=row["co"] - co if row["co"] is not None and co is not None else None,
                    delta_completion=row["completion"] - comp if row["completion"] is not None and comp is not None else None,
                    delta_rpt=row["rpt"] - avg(v["rpt"] for v in values) if row["rpt"] is not None and all(v["rpt"] is not None for v in values) else None,
                    full_att_comparable=row["completion"] == 1 and comp == 1,
                    note="CO差仅描述，不把完成率接近当成相同完成者；规则不是真实最优界"))
        save_csv(self.out / "01_逐回放指标与质量.csv", episodes)
        save_csv(self.out / "02_逐检查点曲线.csv", curves)
        save_csv(self.out / "03_逐模型Best平台与回退.csv", runs)
        save_csv(self.out / "04_同条件逐规则对照.csv", comparisons)
        save_csv(self.out / "05_旧分支标签_未认证.csv", self.probes)
        save_json(self.out / "06_历史回放停摆证据.json", self.replay_diagnostics)
        save_json(self.out / "输入与合同.json", dict(inputs=self.inputs, plans=self.plans,
            trace_hashes={k: sorted(v) for k, v in self.trace_hashes.items()},
            new_training_transitions=0, raw_episodes_unchanged=True))
        save_json(self.out / "读取问题.json", self.issues)
        base_pairs, control_pairs = [], []
        for row in runs:
            context = ("suite", "environment", "k", "fleet", "seed", "stage", "control", "bank_signature")
            bases = [r for r in runs if all(r[k] == row[k] for k in context)
                     and r["method"] in ("UAGMC_SOURCE_L", "SINGLE__R_SOURCE", "J3__R_SOURCE", "SINGLE__M0_BASE", "J3__M0_BASE")]
            if len(bases) == 1 and bases[0]["cell"] != row["cell"]:
                base = bases[0]
                base_pairs.append(dict(suite=row["suite"], cell=row["cell"], reference=base["cell"], seed=row["seed"],
                    delta_best_co=row["best_co"]-base["best_co"], delta_late_co=row["late_co"]-base["late_co"],
                    delta_completion=row["best_completion"]-base["best_completion"],
                    scope="相同suite/stage/control/seed/需求bank；Best仍是探索性选择；未认证全体ATT"))
            if row["control"] != "J3":
                continue
            context = ("suite", "environment", "k", "fleet", "seed", "stage", "arm", "bank_signature")
            singles = [r for r in runs if r["control"] == "LQ" and all(r[k] == row[k] for k in context)]
            if len(singles) == 1:
                single = singles[0]
                control_pairs.append(dict(suite=row["suite"], joint=row["cell"], single=single["cell"], seed=row["seed"],
                    delta_best_co=row["best_co"]-single["best_co"], delta_completion=row["best_completion"]-single["best_completion"],
                    scope="J3减LQ；控制权限和学习通路均可能变化，不是纯交通机制效应"))
        save_csv(self.out / "10_同控制同seed对源基座差.csv", base_pairs)
        save_csv(self.out / "11_同机制同seed联合单侧差.csv", control_pairs)
        return episodes, runs, comparisons

    @staticmethod
    def match_key(r):
        return tuple(str(r.get(k)) for k in ("suite", "environment", "k", "fleet", "control", "trace_key", "eval_seed", "sim_minutes"))


def sources_for(project, explicit):
    if explicit:
        return [Path(p) for p in explicit]
    sources = []
    # 目录优先，避免把服务器当前快照当成旧归档重复样本。
    for suite in SUITES:
        folder = project / "serial_runs" / suite
        if folder.is_dir():
            sources.append(folder)
            continue
        for parent in (project / "experiment_archives", project / "serial_runs"):
            path = parent / (suite + "_DATAONLY.tar.gz")
            if path.is_file():
                sources.append(path)
                break
    combo = project / "experiment_archives/uam_E01_trace_oracle_20261024_DATAONLY.tar.gz"
    if combo.is_file():
        sources.append(combo)
    return sources


def runtime_source(runtime):
    item = _RUNTIMES[runtime]
    text = zlib.decompress(base64.b85decode(item["payload"])).decode("utf-8")
    if digest(text.encode()) != item["sha256"]:
        raise RuntimeError("内嵌运行时校验失败")
    return text


def select_jobs(project, out, args):
    jobs, skipped = [], []
    for suite, runtime in ((SUITES[5], "240"), (SUITES[6], "198")):
        root = project / "serial_runs" / suite
        plan = read_json(root / "SUITE_PLAN.json")
        if not plan:
            skipped.append(dict(suite=suite, reason="只有数据包或尚无本地模型，保留记录审计"))
            continue
        text = runtime_source(runtime).replace("\r\n", "\n")
        hashes = {digest(v.encode()) for v in (text, text.replace("\n", "\r\n"))}
        if plan.get("script_sha256") not in hashes:
            skipped.append(dict(suite=suite, reason="原执行代码版本与内嵌运行时不符，不猜版本加载模型"))
            continue
        pairs = defaultdict(dict)
        for folder in sorted((root / "cells").glob("*")):
            record = read_json(folder / "TASK.json")
            task = record.get("task", {})
            if task.get("environment") != "E1" or not (folder / "TRAIN_END.json").exists():
                continue
            base = task.get("variant") == "M0_BASE" if runtime == "240" else task.get("arm") == "R_SOURCE"
            if not base:
                continue
            checkpoints = {}
            for p in (folder / "checkpoints").glob("step_*.json"):
                cp = read_json(p)
                if not all(cp.get(k) for k in ("model", "vecnorm", "step")):
                    continue
                model, norm = p.parent / Path(cp["model"]).name, p.parent / Path(cp["vecnorm"]).name
                if all(x.is_file() and not x.is_symlink() and inside(x, folder) for x in (model, norm)):
                    checkpoints[int(cp["step"])] = (str(model), str(norm))
            key = (task["k"], task["seed"], task.get("stage", ""))
            pairs[key][actual_control(task)] = (record, checkpoints)
        seen = set()
        for (k, seed, stage), pair in sorted(pairs.items()):
            if k in seen or set(pair) != {"LQ", "J3"}:
                continue
            shared = set(pair["LQ"][1]) & set(pair["J3"][1])
            if not shared:
                continue
            cp = max(shared)
            for control in ("LQ", "J3"):
                record, checkpoints = pair[control]
                model, norm = checkpoints[cp]
                jobs.append(dict(suite=suite, runtime=runtime, root=str(root), task=record["task"],
                    config=record.get("config") or plan["config"], model=model, norm=norm, step=cp,
                    eval_seed=123, out=str(out / "replays" / (runtime + "__" + record["task"]["id"])),
                    episode_seconds=args.episode_seconds, branches=args.branches_per_cell,
                    windows=args.windows, max_branch_ticks=args.max_branch_ticks,
                    recorded_script_sha256=plan.get("script_sha256")))
            seen.add(k)
    jobs = jobs[:args.max_replays - args.max_replays % 2]
    save_json(out / "冻结回放计划.json", dict(jobs=jobs, skipped=skipped,
        selection="各K最小共同seed、共同最大可用checkpoint；不按ATT筛选，不宣称代表全部seed"))
    return jobs


def physical_snapshot(env, module):
    s = env.scenario
    candidates = tuple(str(v) for v in module.CANDIDATES[env.k])
    planes = list(getattr(s, "_all_evtols", {}).values())
    q = {v: len(s.vertiports.vertiport_list[v].person_list) for v in candidates}
    idle = {v: sum(e.state.name == "IDLE" and not e.passenger_ids for e in s.vertiports.evtols_at_vertiport.get(v, [])) for v in candidates}
    signature = dict(time=s.time, finished=sorted(s.finished_ids), queues=q,
        planes=sorted((str(e.id), e.state.name, str(e.current_vertiport_id), str(getattr(e, "target_vertiport_id", "")),
            float(e.remaining_time), float(e.battery_kwh), sorted(e.passenger_ids)) for e in planes),
        persons=sorted((str(pid), str(p.state), str(getattr(p, "sub_state", "")),
            float(getattr(p, "current_timer", 0) or 0), str(getattr(p, "origin_vertiport_id", ""))) for pid, p in s.persons.persons.items()))
    return dict(time=float(s.time), queues=q, idle=idle, aircraft_states=dict(Counter(e.state.name for e in planes)),
                fingerprint=digest(json.dumps(signature, sort_keys=True).encode()))


def replay_worker(jobfile):
    """只加载自己有hash配对的冻结权重；禁止调用learn/train或更新归一化。"""
    job = read_json(jobfile)
    output = Path(job["out"])
    os.chdir(output)
    sys.dont_write_bytecode = True
    os.environ.update(OMP_NUM_THREADS="1", MKL_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", NUMEXPR_NUM_THREADS="1",
        UAM_STRICT_MODE="E1", UAM_STRICT_FLEET="12", UAM_STRICT_LOG_EVENTS="1")
    import torch
    import numpy as np
    torch.set_num_threads(1)
    torch.set_num_interop_threads(1)
    name = "uam_gap_frozen_" + job["runtime"]
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[name] = module
    exec(compile(runtime_source(job["runtime"]), "<trusted_frozen_runtime>", "exec"), module.__dict__)
    root, task = Path(job["root"]), job["task"]
    snapshot = module.source_snapshot()
    native = root / "_author_source" / snapshot["commit"]
    for rel, sha in snapshot["sha256"].items():
        path = native / rel
        if path.is_symlink() or not inside(path, native) or not path.is_file() or digest(path) != sha:
            raise RuntimeError("封存作者源码缺失或校验失败：" + rel)
    module.initialize_full_runtime()
    module.activate_source(root, task["k"])
    import logging
    from loguru import logger
    logger.remove()
    logging.disable(logging.CRITICAL)
    for clsname, cls in list(module.__dict__.items()):
        if isinstance(cls, type) and cls.__module__ == name:
            globals()[clsname] = cls
    before = {k: digest(job[k]) for k in ("model", "norm")}
    model = module.FullPPO.load(job["model"], device="cpu")
    class OwnNorm(pickle.Unpickler):
        def find_class(self, mod, cls):
            if mod == "__main__" and cls in module.__dict__:
                return module.__dict__[cls]
            return super().find_class(mod, cls)
    with Path(job["norm"]).open("rb") as f:
        norm = OwnNorm(f).load()
    norm.training = False
    norm.norm_reward = False
    def no_training(*a, **kw):
        raise RuntimeError("本文件禁止新增训练或网络更新")
    model.learn = no_training
    model.train = no_training
    config = job["config"]
    trace = Path((config.get("validation_traces") or [config["trace"]])[0])
    if not trace.is_file() or trace.is_symlink() or not inside(trace, root):
        raise RuntimeError("训练/验证trace不在本实验根内；不猜路径或打开测试bank")
    horizon = int(config["eval_horizon"])
    started = time.perf_counter()
    tape, states, samples, branch_rows = [], {}, [], []
    # 固定时间抽样，不能只挑失败状态；每格仅两点是计算预算，不是功效论证。
    with trace.open(encoding="utf-8-sig", newline="") as f:
        demand_end = max(float(r["time"]) for r in csv.DictReader(f))
    target_times = [min(horizon, demand_end) * (i + 1) / (job["branches"] + 1) for i in range(job["branches"])]
    branch_ticks = 0

    def one_run(target=None, forced=None):
        nonlocal branch_ticks
        from stable_baselines3.common.utils import set_random_seed
        set_random_seed(job["eval_seed"])
        env = module.FullEnv(root, task["k"], horizon, str(trace), task["method"], task["environment"])
        obs, _ = env.reset(seed=job["eval_seed"])
        counts = [0] * task["k"]
        area, local_cost = 0., 0.
        threshold_costs = {}
        tick, activated, branch_start = 0, False, None
        try:
            with torch.no_grad():
                while True:
                    if time.perf_counter() - started > job["episode_seconds"]:
                        raise TimeoutError("单worker墙钟预算用尽，不把它记为物理停摆")
                    s = env.scenario
                    t0 = float(s.time)
                    unfinished = sum(pid not in set(s.finished_ids) for pid in s.persons.persons)
                    area += unfinished
                    active = bool(s.waiting_decisions)
                    pre = norm.normalize_obs(obs[None])
                    if target is not None and tick < target:
                        p, a = tape[tick]
                        pending_raw = env.prepare_step(p)
                    else:
                        if target is not None and tick == target:
                            if physical_snapshot(env, module)["fingerprint"] != states[target]["fingerprint"]:
                                raise RuntimeError("动作前缀重建不一致，拒绝生成不可比的分支标签")
                            if not np.array_equal(obs, np.asarray(states[target]["raw_observation"], dtype=obs.dtype)):
                                raise RuntimeError("动作前缀的完整观测不一致，拒绝分支")
                            random.setstate(states[target]["rng_py"])
                            np.random.set_state(states[target]["rng_np"])
                            torch.set_rng_state(states[target]["rng_torch"])
                            activated, branch_start = True, float(s.time)
                        if target is None and active and len(states) < len(target_times) and s.time >= target_times[len(states)]:
                            snap = physical_snapshot(env, module)
                            snap.update(rng_py=random.getstate(), rng_np=np.random.get_state(), rng_torch=torch.get_rng_state())
                            # 额外前向只在eval模式执行，并还原RNG；不训练解码探针。
                            snap["raw_observation"] = obs.tolist()
                            snap["normalized_observation"] = pre[0].tolist()
                            if not model.policy.training:
                                hidden = model.policy.features_extractor(torch.as_tensor(pre))
                                snap["passenger_base_hidden"] = hidden[0].cpu().tolist()
                                random.setstate(snap["rng_py"])
                                np.random.set_state(snap["rng_np"])
                                torch.set_rng_state(snap["rng_torch"])
                            states[tick] = snap
                        committed_audit = None
                        if target is None and hasattr(module, "_committed"):
                            committed = module._committed(s, task["k"])
                            committed_audit = [dict(queue=x["queue"], idle=x["idle"], incoming_count=len(x["incoming"]),
                                next_incoming=min(x["incoming"], default=None), committed_ready_count=len(x["ready"]),
                                next_committed_ready=min(x["ready"], default=None)) for x in committed]
                        action, _, prob = model.policy.sample_passenger(torch.as_tensor(pre), True)
                        p = int(action[0]) if not (activated and tick == target) else int(forced[0])
                        pending_raw = env.prepare_step(p)
                        pending = norm.normalize_obs(pending_raw[None])
                        pending[:, :env.schema.pack] = pre[:, :env.schema.pack]
                        action = model.policy.sample_return(torch.as_tensor(pending), torch.as_tensor([p]), True)
                        a = int(action[0])
                        if activated and tick == target and forced[1] is not None:
                            if pending_raw[env.schema.return_mask][forced[1]] < .5:
                                return {"illegal": True}
                            a = int(forced[1])
                        if target is None:
                            record = dict(tick=tick, time=t0, passenger_active=active,
                                passenger=p, aircraft=a, return_mask=pending_raw[env.schema.return_mask].tolist(),
                                source_current_frame=obs[env.schema.history-env.schema.frame:env.schema.history].tolist(),
                                fingerprint=physical_snapshot(env, module)["fingerprint"])
                            if committed_audit is not None:
                                record["pre_committed_station_summary"] = committed_audit
                            samples.append(record)
                    if active:
                        counts[p] += 1
                    obs, reward, done, info = env.finish_step(a)
                    dt = float(s.time) - t0
                    if dt < 0 or dt > 1.000001:
                        raise RuntimeError("物理时间步不在0至1分钟，不能冒称精确左端点人时")
                    if target is None:
                        tape.append((p, a))
                    if activated:
                        branch_ticks += 1
                        if branch_ticks > job["max_branch_ticks"]:
                            raise TimeoutError("达到分支步数上限")
                        local_cost += unfinished * dt
                        elapsed = float(s.time) - branch_start
                        for window in job["windows"]:
                            if elapsed >= window and window not in threshold_costs:
                                threshold_costs[window] = dict(cost=local_cost, unfinished=sum(pid not in set(s.finished_ids) for pid in s.persons.persons),
                                    elapsed=elapsed, terminal_correction="无尾值；固定窗截断人时，仅局部诊断")
                        if elapsed >= max(job["windows"]) or done:
                            return dict(windows=threshold_costs, illegal=False, early_truncation=elapsed < max(job["windows"]))
                    if done:
                        result = module._base_episode_metrics(env, counts, area)
                        result["decision_trace"] = samples
                        result["final_station_queues"] = physical_snapshot(env, module)["queues"]
                        result["eval_seed"] = job["eval_seed"]
                        result["trace_sha256"] = digest(trace)
                        return result
                    tick += 1
        finally:
            env.close()

    baseline = one_run()
    save_json(output / "冻结回放.json", dict(task=task, step=job["step"], episodes=[baseline]))
    original = read_json(root / "cells" / task["id"] / "evaluation" / f"step_{job['step']:09d}.json")
    old = [e for e in original.get("episodes", []) if e.get("eval_seed") == job["eval_seed"] and e.get("mode", "DET") == "DET"
           and (not e.get("trace_sha256") or e["trace_sha256"] == digest(trace))]
    validation = dict(original_available=len(old) == 1, metrics={}, comparable=False)
    if len(old) == 1:
        for key in ("generated", "finished", "ATT_completed_only", "restricted_person_time_per_generated"):
            a, b = number(old[0].get(key)), number(baseline.get(key))
            validation["metrics"][key] = a - b if a is not None and b is not None else None
        validation["comparable"] = all(v is not None and abs(v) < 1e-7 for v in validation["metrics"].values())
    save_json(output / "原回放复现核验.json", validation)
    if not validation["comparable"]:
        raise RuntimeError("原逐回放缺失/不唯一或冻结回放不一致；已留补采记录，但不继续动作归因")
    hidden_rows = [{"tick": tick, **{k:v for k,v in s.items() if not k.startswith("rng_")}} for tick,s in states.items()]
    save_json(output / "冻结表示样本.json", dict(samples=hidden_rows,
        scope="冻结模型乘客基础特征；不是全部决策通路，也不凭距离或解码失败宣布信息不存在"))
    # 重建同状态只强制当前两类动作，随后始终使用同一冻结后续策略。
    for tick in states:
        for p in range(task["k"]):
            aircraft_options = range(task["k"]) if actual_control(task) == "J3" else [None]
            for a in aircraft_options:
                r = one_run(tick, (p, a))
                branch_rows.append(dict(state_tick=tick, state_time=states[tick]["time"], passenger=p, aircraft=a, **r))
    after = {k: digest(job[k]) for k in ("model", "norm")}
    if before != after:
        raise RuntimeError("模型或归一化文件变化，不接受本回放")
    save_json(output / "分支结果.json", dict(job=job, results=branch_rows, new_training_transitions=0,
        unchanged_weights=before, branch_ticks=branch_ticks,
        scope="离线模拟器干预；回放会逐步揭示同一CSV未来，不能称为合法在线规划收益或全局Q；原策略不接收未揭示CSV",
        random_scope="同前缀重建并恢复Python/NumPy/Torch RNG；后续动作相关随机消耗不保证事件级CRN",
        completion=baseline.get("completion"), elapsed_seconds=time.perf_counter()-started))
    save_json(output / "END.json", dict(status="COMPLETE", new_training_transitions=0))


def execute_jobs(jobs, args, out):
    results = []
    for i, job in enumerate(jobs):
        folder = Path(job["out"])
        folder.mkdir(parents=True, exist_ok=True)
        jobfile = folder / "JOB.json"
        if jobfile.exists() and read_json(jobfile) != job:
            raise RuntimeError("已有回放任务合同不同，不覆盖：" + str(jobfile))
        if (folder / "END.json").exists():
            results.append(dict(cell=job["task"]["id"], status="RESUMED_COMPLETE", folder=str(folder)))
            continue
        save_json(jobfile, job)
        print(f"[冻结回放 {i+1}/{len(jobs)}] {job['task']['id']}", flush=True)
        with (folder / "worker.log").open("a", encoding="utf-8") as f:
            try:
                proc = subprocess.run([sys.executable, "-B", str(Path(__file__).resolve()), "--worker", str(jobfile)],
                    cwd=folder, stdout=f, stderr=subprocess.STDOUT, timeout=args.worker_seconds,
                    env=os.environ | {"OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1", "OPENBLAS_NUM_THREADS": "1"})
                status = "COMPLETE" if proc.returncode == 0 and (folder / "END.json").exists() else "FAILED_SEE_LOG"
            except subprocess.TimeoutExpired:
                status = "WORKER_TIMEOUT_NOT_DEADLOCK"
        results.append(dict(cell=job["task"]["id"], status=status, folder=str(folder)))
        save_json(out / "回放进度.json", dict(completed=i+1, total=len(jobs), results=results, new_training_transitions=0))
    return results


def summarize_branches(out):
    """只描述局部代价矩阵，不自动筛选方法或认证假说。"""
    rows, horizons = [], []
    for path in sorted((out / "replays").glob("*/分支结果.json")):
        obj = read_json(path)
        job = obj.get("job", {})
        grouped = defaultdict(dict)
        for r in obj.get("results", []):
            if r.get("illegal"):
                continue
            for window, value in r.get("windows", {}).items():
                if number(value.get("cost")) is not None:
                    grouped[(r["state_tick"], int(window))][(r["passenger"], r.get("aircraft"))] = value["cost"]
        rankings = defaultdict(dict)
        for (tick, window), matrix in grouped.items():
            best = min(matrix, key=lambda a: (matrix[a], str(a)))
            best_set = [a for a in matrix if abs(matrix[a] - matrix[best]) <= 1e-9]
            rankings[tick][window] = best_set
            interaction = []
            keys = list(matrix)
            for p, a in keys:
                if a is None:
                    continue
                for pp, aa in keys:
                    if p < pp and a < aa and (p, aa) in matrix and (pp, a) in matrix:
                        interaction.append(matrix[(p,a)] - matrix[(p,aa)] - matrix[(pp,a)] + matrix[(pp,aa)])
            rows.append(dict(cell=job.get("task", {}).get("id"), state_tick=tick, window=window,
                candidates=len(matrix), best_action=best, tied_best_actions=best_set, best_cost=matrix[best],
                cost_range=max(matrix.values())-min(matrix.values()),
                max_abs_cross_difference=max(map(abs, interaction)) if interaction else None,
                scope="固定后续策略/离线未来CSV/截断窗；交互非可加不等于现有策略学不到"))
        for tick, rank in rankings.items():
            best_sets = [set(actions) for actions in rank.values()]
            horizons.append(dict(cell=job.get("task", {}).get("id"), state_tick=tick, rankings=rank,
                ranking_changed=any(a.isdisjoint(b) for i,a in enumerate(best_sets) for b in best_sets[i+1:]),
                scope="不同截断窗口的排序敏感性，不是长期ATT收益证明"))
    save_csv(out / "08_局部联合代价矩阵摘要.csv", rows)
    save_csv(out / "09_窗口排序敏感性.csv", horizons)
    return rows, horizons


def table(rows, fields, limit=25):
    def val(x):
        return "NA" if x is None else f"{x:.4f}" if isinstance(x, float) else str(x)
    return "<table><thead><tr>" + "".join("<th>"+html.escape(k)+"</th>" for k in fields) + "</tr></thead><tbody>" + "".join(
        "<tr>"+"".join("<td>"+html.escape(val(row.get(k)))+"</td>" for k in fields)+"</tr>" for row in rows[:limit]) + "</tbody></table>"


def write_report(out, episodes, runs, comparisons, audit, replay_results):
    totals = Counter(r["terminal_class"] for r in episodes)
    coverage = dict(episodes=len(episodes), models=len(runs), paired_rule_rows=len(comparisons),
        decision_trace_episodes=sum(r["decision_samples"] > 0 for r in episodes),
        timeline_episodes=sum(r["timeline_samples"] > 0 for r in episodes), terminal_classes=dict(totals),
        record_issues=len(audit.issues), new_training_transitions=0)
    checks = [
        ("D0 数据/指标", "01、02、03、04表", "核对删失、CO与全体ATT、同bank对照；不将低CO自动判胜", "有指标错误先重算分析，不训练"),
        ("D1 结论稳定性", "逐模型Best/平台/回退，保留所有seed", "分开坏平台、后期回退、停摆；不自动给假说打分", "先定位不同seed的错误类型，不先换优化器"),
        ("D2 时间输入遗漏", "decision_trace的原始时间槽与物理ready摘要", "只能证明输入缺口，不能证明STIN压缩或ATT因果效应", "缺决策明细先冻结回放；有差异再检查动作价值"),
        ("D3 表示是否丢失", "可选回放导出原输入、归一化输入和基础隐藏表示，不训练探针", "基础隐藏表示不等于全部候选通路；没有自动认证编码丢信息", "先检查确定性输入碰撞及动作标签，距离相近本身不是证明"),
        ("D4 等待/服务", "快照互斥四分类＋飞机事件", "采样点不是精确分钟；未记载的事件不能插值为事实", "缺逐分钟明细先回放补记，不改物理"),
        ("D5 短长时域", "离线同状态分支15/60分钟", "窗口排名反转只是诊断线索；未加统一尾值，不是全局Q", "只有长期真实成本与合法在线规划也支持才考虑WM"),
        ("D6 联合依赖", "同状态合法乘客×飞机动作分支", "固定后续策略下的局部交互，不证明必须MARL", "先与枚举、规则飞机侧比较；权限死锁归入环境边界"),
        ("D7 文献缺口", "三类候选问题＋近邻任务权限表", "任何数值程序都不能认证全球新颖性", "证实频率与成本后，再针对具体机制复核最接近文献"),
    ]
    save_csv(out / "07_诊断边界与后续处理.csv", [dict(id=a, evidence=b, limit=c, next=d) for a,b,c,d in checks])
    save_json(out / "覆盖与缺证据.json", coverage)
    body = "<h1>UAM无训练缺口审计</h1><p>新增训练步数：0。没有拟合探针、更新策略、改变环境或自动启动消融。既有训练进程未被本脚本停止。</p>"
    body += "<h2>先看是否具备解释条件</h2><pre>"+html.escape(json.dumps(coverage, ensure_ascii=False, indent=2))+"</pre>"
    body += "<p>NA是缺证据，不是零损失。模型数是有曲线的训练run，不是独立新实验数；48M含暖启动，跨合同不正式排名。档案Best是内部探索性选择，不冒称独立测试。</p>"
    body += "<h2>诊断与结果处理</h2>"+table([dict(诊断=a,证据=b,边界=c,后续=d) for a,b,c,d in checks],["诊断","证据","边界","后续"])
    body += "<h2>逐模型样例；完整数据见CSV</h2>"+table(runs,["suite","cell","best_co","best_completion","late_co","rollback"])
    body += "<h2>同条件逐规则差值；负值表示前项较低，不自动代表胜出</h2>"+table(comparisons,["cell","rule","delta_co","delta_completion","delta_rpt","full_att_comparable"])
    body += "<h2>冻结回放执行状态</h2>"+table(replay_results,["cell","status"])
    body += "<h2>必须保留的竞争解释</h2><p>输入遗漏、编码/利用不足、长期价值不足、两类动作依赖、奖励目标不一致、受限执行器停摆、统计删失与需求/初始化差异。排除一个不等于其余某个被证明。</p>"
    body += "<h2>训练重新开放条件</h2><p>人工明确写出：仍无法区分的两个解释、为什么记录/冻结回放/合法动作干预不能区分、最小需要更新哪部分、其余冻结什么、什么结果支持/反对。用户再次授权后才写训练；预算不会自动解锁。</p>"
    body += "<p>文献依据见本文件配套《无训练缺口审计_实验设计报告》；Kassis等Scientific Agent Skills (2026)用于单位、干预与证据边界约束，不是UAM实证来源。</p>"
    page = '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>UAM无训练诊断</title><style>body{font:17px/1.7 system-ui;margin:35px auto;max-width:1250px;padding:0 20px;color:#18334a}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #cbd8e2;padding:8px;text-align:left;vertical-align:top}th{background:#eaf1f7}pre{white-space:pre-wrap}h2{margin-top:32px}</style>'+body+'</html>'
    (out / "诊断报告.html").write_text(page, encoding="utf-8")
    save_json(out / "END.json", dict(version=VERSION, status="COMPLETE_WITH_EXPLICIT_LIMITS", **coverage))


def pack(out, project):
    archive = project / "experiment_archives" / (out.name + "_DATAONLY.tar.gz")
    archive.parent.mkdir(parents=True, exist_ok=True)
    if archive.exists():
        raise RuntimeError("数据包已存在，不覆盖；请换新的输出目录名")
    with tarfile.open(archive, "w:gz") as arc:
        for path in sorted(out.rglob("*")):
            if path.is_file() and not path.is_symlink() and path.suffix not in (".zip", ".pkl", ".pt", ".pth"):
                arc.add(path, arcname=out.name + "/" + path.relative_to(out).as_posix(), recursive=False)
    print("[数据包]", archive, flush=True)


def main():
    parser = argparse.ArgumentParser(description="禁止新增训练的UAM记录/冻结回放诊断")
    parser.add_argument("--project", default=str(Path(__file__).resolve().parent))
    parser.add_argument("--out", default="analysis_reports/uam_gap_notrain_20261030_v1")
    parser.add_argument("--mode", choices=("records", "all"), default="records")
    parser.add_argument("--input", action="append", default=[])
    parser.add_argument("--trust-own-checkpoints", action="store_true")
    parser.add_argument("--max-replays", type=int, default=12)
    parser.add_argument("--branches-per-cell", type=int, default=2)
    parser.add_argument("--windows", type=int, nargs="+", default=[15, 60])
    parser.add_argument("--max-branch-ticks", type=int, default=30000)
    parser.add_argument("--episode-seconds", type=int, default=150)
    parser.add_argument("--worker-seconds", type=int, default=210)
    parser.add_argument("--max-files", type=int, default=100000)
    parser.add_argument("--max-read-gib", type=float, default=4.)
    parser.add_argument("--max-member-mib", type=int, default=32)
    parser.add_argument("--pack", action="store_true")
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--worker", help=argparse.SUPPRESS)
    args = parser.parse_args()
    if args.worker:
        replay_worker(args.worker)
        return
    if not 0 <= args.branches_per_cell <= 4 or not 0 <= args.max_replays <= 24:
        parser.error("每格分支状态须0至4；回放上限0至24")
    if not args.windows or min(args.windows) <= 0 or max(args.windows) > 180:
        parser.error("窗口须在1至180分钟内")
    if args.mode == "all" and not args.trust_own_checkpoints:
        parser.error("模型pickle仅限自己的可信文件；需--trust-own-checkpoints，或仅用--mode records")
    project = Path(args.project).resolve()
    out = (project / args.out).resolve()
    if not inside(out, project / "analysis_reports") or out.is_symlink():
        raise RuntimeError("输出只允许在项目analysis_reports内，拒绝覆盖原实验根")
    if out.exists() and any(out.iterdir()) and not args.resume:
        raise RuntimeError("已有诊断目录不覆盖；请用--out指定新的名字")
    out.mkdir(parents=True, exist_ok=True)
    previous = read_json(out / "协议锁.json")
    current_args = {k:v for k,v in vars(args).items() if k not in ("resume", "pack")}
    if previous and (previous.get("script_sha256") != digest(__file__) or
                     {k:v for k,v in previous.get("arguments", {}).items() if k not in ("resume", "pack")} != current_args):
        raise RuntimeError("断点恢复代码/参数不同，请另用输出目录，不混合同")
    save_json(out / "协议锁.json", dict(version=VERSION, arguments=vars(args), script_sha256=digest(__file__),
        new_training_transitions=0, probe_fitting=False, checkpoint_selection="共同最大可用步数；不按性能筛选",
        information_boundary="真未来分支仅为离线诊断；原策略输入不追加未揭示请求"))
    audit = Audit(args, out)
    sources = sources_for(project, args.input)
    if not sources:
        raise RuntimeError("没有找到支持的实验目录/数据包；不会生成空白成功结论")
    audit.scan(sources)
    episodes, runs, comparisons = audit.finish()
    results = []
    if args.mode == "all":
        jobs = select_jobs(project, out, args)
        results = execute_jobs(jobs, args, out)
    summarize_branches(out)
    write_report(out, episodes, runs, comparisons, audit, results)
    if args.pack:
        pack(out, project)
    print("[完成] 新训练0步；报告：", out / "诊断报告.html", flush=True)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc()
        sys.exit(1)
